diff --git a/infra/dumps.tf b/infra/dumps.tf
new file mode 100644
index 0000000..9d26acb
--- /dev/null
+++ b/infra/dumps.tf
@@ -0,0 +1,80 @@
+resource "aws_s3_bucket" "db_dumps" {
+  bucket = "shop-db-dumps-${var.env}"
+}
+
+resource "aws_s3_bucket_ownership_controls" "db_dumps" {
+  bucket = aws_s3_bucket.db_dumps.id
+
+  rule {
+    object_ownership = "BucketOwnerEnforced"
+  }
+}
+
+resource "aws_s3_bucket_public_access_block" "db_dumps" {
+  bucket = aws_s3_bucket.db_dumps.id
+
+  block_public_acls       = true
+  block_public_policy     = true
+  ignore_public_acls      = true
+  restrict_public_buckets = true
+}
+
+resource "aws_s3_bucket_server_side_encryption_configuration" "db_dumps" {
+  bucket = aws_s3_bucket.db_dumps.id
+
+  rule {
+    apply_server_side_encryption_by_default {
+      sse_algorithm = "AES256"
+    }
+  }
+}
+
+resource "aws_s3_bucket_lifecycle_configuration" "db_dumps" {
+  bucket = aws_s3_bucket.db_dumps.id
+
+  rule {
+    id     = "expire-nightly-dumps"
+    status = "Enabled"
+
+    filter {}
+
+    expiration {
+      days = 35
+    }
+
+    abort_incomplete_multipart_upload {
+      days_after_initiation = 7
+    }
+  }
+}
+
+data "aws_iam_policy_document" "db_dumps_require_tls" {
+  statement {
+    sid    = "DenyInsecureTransport"
+    effect = "Deny"
+
+    principals {
+      type        = "*"
+      identifiers = ["*"]
+    }
+
+    actions = ["s3:*"]
+    resources = [
+      aws_s3_bucket.db_dumps.arn,
+      "${aws_s3_bucket.db_dumps.arn}/*",
+    ]
+
+    condition {
+      test     = "Bool"
+      variable = "aws:SecureTransport"
+      values   = ["false"]
+    }
+  }
+}
+
+resource "aws_s3_bucket_policy" "db_dumps_require_tls" {
+  bucket = aws_s3_bucket.db_dumps.id
+  policy = data.aws_iam_policy_document.db_dumps_require_tls.json
+
+  depends_on = [aws_s3_bucket_public_access_block.db_dumps]
+}
